import net

fn serve(conn: NetConn) {
    defer net.close(conn)
    net.copy(conn, conn)
}

var listener = net.listen(9001, 1024)!
while (true) {
    var conn = net.accept(listener)
    if (conn != null) {
        go serve(conn!)
    }
}

