import { Capabilities, U32x4 } from simd

fn main() {
    var words = Array<u32>([1, 2, 3, 4])
    var view: Slice<u32> = words[:]
    var result = U32x4.load(view).add(U32x4.splat(10))

    print(result.extract(2))
    print(Capabilities.nativeBytes() >= 16)
}

main()
